"sec_ses_end": "Fechá-la",
"sec_ses_end_others": "Fechar todas as outras",
"sec_ses_none": "Não há sessões para mostrar.",
"sec_ses_ended": "Sessão fechada.",
"sec_rem_title": "Usar o servidor de fora de casa",
"sec_rem_help": "Abra o servidor à Internet só por uma porta: um proxy inverso com certificado válido (o perfil TLS). O broker e os nós nunca se publicam. Carregue no botão a partir de um telemóvel com dados móveis para ver como o servidor o vê.",
"sec_rem_check": "Verificar como o servidor me vê",
"sec_rem_ip": "Endereço que o servidor vê",
"sec_rem_origin": "Conta como",
"sec_rem_secure": "Cookie seguro",
"sec_rem_proxy": "Proxy de confiança",
"sec_rem_policy": "Política do segundo fator",
"sec_rem_yes": "sim",
"sec_rem_no": "não",
"sec_rem_warn_local": "O servidor vê-o dentro de casa. Se está com dados móveis, o proxy não está a passar o seu endereço: indique abaixo o proxy de confiança.",
"sec_cfg_title": "Definições do acesso de fora",
"sec_cfg_help": "Guardam-se no ficheiro de definições do servidor e o servidor reinicia para as aplicar. Só para administradores.",
