"sec_cfg_totp_remote": "Obrigatório de fora de casa",
"sec_cfg_totp_always": "Obrigatório sempre",
"sec_cfg_policy": "O que pode fazer uma sessão de fora",
"sec_cfg_policy_full": "Tudo (o crítico pede a palavra-passe de novo)",
"sec_cfg_policy_operate": "Ver e manobrar o alarme; administrar só de casa ou da VPN",
"sec_cfg_policy_view": "Só olhar",
"sec_cfg_ttl": "Horas que dura uma sessão de fora",
"sec_cfg_idle": "Minutos sem uso antes de terminar",
"sec_cfg_save": "Guardar e reiniciar o servidor",
